INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65521768', 65521768, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL KEKAYAAN INTELEKTUAL', 'Belanja Pemeliharaan Peralatan dan Mesin Lainnya Pemeliharaan Aplikasi DJKI berupa Pemeliharaan Aplikasi Indikasi Geografis, Desain Tata Letak Sirkuit Terpadu, Rahasia Dagang, Portal Web Djki pada Direktorat Jenderal Kekayaan Intelektual TA 2026', 'Jasa Lainnya', 'Tender', 'DKI Jakarta, Jakarta Selatan (Kota)', 540000000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'melakukan pemeliharaan aplikasi Indikasi Geografis, DTLST, RD dan Portal web DJKI dengan memastikan seluruh aplikasi berfungsi stabil, menyelesaikan permasalahan teknis (bug fixing) yang ditemukan pada aplikasi secara efisien, menciptakan dokumentasi yang lengkap daan terstruktur, menyedikan mekanisme backup dan recovery sistem untuk menjaga keberlangsungan pelayanan, melakukan pengecekan dan penyelesaian kendala aplikasi, mengakomodasi perubahan sesuai kebutuhan pengguna aplikasi untuk memastikan aplikasi tetap relevan', 'Aplikasi Indikasi Geografis : membuat fitur pada saat pengajuan keberatan, sanggahan, komisi banding, penambahan fitur pada aplikasi Indikasi geografis. Aplikasi DTLST : melakukan pemeliharaan secara preventif untuk mencegah terjadinya kerusakan pada aplikasi baik secara periodik maupun insidental, melakukan pemeliharaan secara kolektif, melakukan bug fixed dan/atau update patch terhadap aplikasi, melakukan perubahan atau modifikasi aplikasi menyesuaikan kebutuhan, menyusun coding, melakukan pengujian fungsi sub-sub modul aplikasi, melakukan pelatihan, rapat koordinasi, laporan pelaksanaan hasil pekerjaan dan penyerahan source code aplikasi serta manual book Aplikasi Rahasia Dagang : melaksanakan pemeliharaan secara preventif, korektif, melaksanakan bug fixed dan/atau update patch terhadap aplikasi, melakukan perubahan atau modifikasi aplikasi untuk mendukung penyesuaian kebutuhan, menyusun coding, melakukan pengujiaan fungsi sub-sub modul aplikasi, melakukan pelatihn, rapat koordinasi dan evaluasi, laporan pelaksanaan hasil pekerjaan. Aplikaasi Portal Web DJKI : melaksanakan perubahan atau modifikasi tampilan dan fitur portal web DJKI untuk mendukung penyesuaian kebutuhan, menyusun coding, melakukan pengujian fungsi sub-sub modul aplikasi atau error-bug testing oleh penyedia, melakukan pelatihan, rapat koordinasi, laporan pelaksanaan hasil pekerjaan dan penyerahaan source code aplikasi serta manual book.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2180403);
