INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65490147', 65490147, 'analyze_legacy', 'Kementerian Kependudukan dan Pembangunan Keluarga/BKKBN', 'central', 'Perwakilan BKKBN Provinsi Kalimantan Selatan', 'Belanja Barang Bantuan Lainnya Untuk Diserahkan Kepada Masyarakat/Pemda', 'Barang', 'E-Purchasing', 'Kalimantan Selatan, Banjarmasin (Kota)', 5405357000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Plester Steril ( 23240, BH, @ 7100 ); 2. Povidon Iodine ( 5810, BH, @ 5000 ); 3. Asam Mefenamat ( 23240, BH, @ 3300 ); 4. Doek Steril ( 23240, BH, @ 7500 ); 5. Syringe ( 23240, BH, @ 1730 ); 6. Implant 1 Batang ( 1100, BH, @ 307000 ); 7. Suntikan Kombinasi ( 8400, VIAL, @ 16000 ); 8. Pil Kombinasi ( 20800, CYCLE, @ 3000 ); 9. Implan 2 Batang ( 22140, SET, @ 182000 ); 10. Syringe ( 8400, BUAH, @ 2000 ); 11. IUD ( 1950, SET, @ 15500 ); 12. Kasa Steril ( 6760, BH, @ 6500 ); 13. Masker ( 2300, BH, @ 300 ); 14. Lidokain ( 23240, PKT, @ 3300 ); 15. Sarung tangan ( 23240, BH, @ 8080 );', '1. Memiliki Nomer Izin Edar dari BPOM RI yang masih berlaku, 2. Mempunyai sertifikat CPOB dari BPOM RI yang masih berlaku 3. Mempunyai sertifikat CDOB dari BPOM RI yang masih berlaku untuk PBF 4. Memiliki Certificate Of Analysis (CoA) yang memenuhi syarat 5. Masa kadaluarsa minimal 2,5 tahun sejak diterima di gudang Perwakilan BKKBN Provinsi Kalimantan Selatan 6. Menggunakan Logo Baru BKKBN, 7. Informasi produk dan penandaan pada kemasan mengikuti persyaratan dalam Nomor Ijin Edar produk Implan dari BPOM dan informasi tambahan dari BKKBN sebagai berikut: a) Individual Pack (1) Pada setiap individual pack harus tercantum nomor batch/lot, nomor registrasi, waktu produksi (bulan, tahun) dan masa kadaluarsa (tanggal, bulan, tahun). (2) Pada setiap individual pack tercantum nama produk yang disesuaikan dengan nama produk di dokumen izin edar. (3) Pada setiap individual pack harus tercantum tulisan “BKKBN APBN Tahun Anggaran 2026” dengan warna hitam/biru dan tulisan “Tidak Diperjualbelikan” dengan warna merah. (4) Jumlah individual pack yang dimasukkan kedalam inner box disesuaikan dengan kemasan yang tercantum dalam NIE. b) Inner Box (Box Kecil) (1) Setiap inner box dilengkapi dengan petunjuk pemakaian dalam bahasa Indonesia, 1 copy untuk setiap blister pil KB. (2) Pada setiap inner box tercantum nama produk yang disesuaikan dengan nama produk di dokumen izin edar. (3) Setiap inner box tertulis nomor batch/lot, nomor registrasi, waktu produksi (bulan, tahun) dan masa kadaluarsa (tanggal, bulan, tahun). (4) Pada inner box harus tercantum “BKKBN APBN Tahun Anggaran 2026” dengan warna hitam/biru dan “Tidak diperjualbelikan” dengan warna merah. (5) Jumlah inner box yang dimasukkan ke dalam outer box (box besar) disesuaikan dengan kemasan yang tercantum dalam NIE. c) Outer Box (Box Besar) (1) Pada setiap outer box tercantum nama produk yang disesuaikan dengan nama produk di dokumen izin edar. (2) Pada outer box tercantum nomor batch/lot, nomor registrasi, waktu produksi (bulan, tahun) dan masa kadaluarsa (tanggal, bulan, tahun) tertulis pada dua sisi. (3) Setiap satu outer box tercantum tulisan ”BKKBN APBN Tahun Anggaran 2026” dengan warna hitam/biru dan tulisan “Tidak diperjualbelikan” dengan warna merah. (4) Ketebalan karton outer box menyesuaikan dengan jenis dan berat produk agar dapat terjamin keamanan, mutu, dan manfaat produk.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2186421);
