INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65489459', 65489459, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN LANJUTAN', 'Procurement of Invasive Cardiology Equipment Batch II', 'Barang', 'Tender', 'DKI Jakarta, Jakarta Selatan (Kota)', 152063122799, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 0, 0, '1 Paket', 'Pengadaan Peralatan Invasive Cardiology Tahap 2: Lot 1: Intra-aortic Ballon Pump (IABP) (13 unit) Lot 2: Rotational Atherectomy (28 unit) Lot 3: Optical Coherence Tomography (18 unit) Lot 4: Invasive Hemodynamic Monitor (15 unit)', 'Lot 1: Intra-aortic Ballon Pump (IABP) : Unit bantu sirkulasi yang menghasilkan kontra-pulsasi mekanis untuk mengurangi beban kerja jantung dan meningkatkan aliran darah koroner dan serebral; Lot 2: Rotational Atherectomy : Sistem yang dirancang untuk secara mekanis mengganggu dan/atau menghilangkan plak ateroma dari dinding arteri. Terdapat berbagai jenis perangkat aterektomi: orbital, rotasional, laser, dan terarah. Sistem ini terdiri dari perangkat yang dirancang berbeda untuk memotong, mengikis, mengikis, atau menguapkan plak tersebut; Lot 3: Optical Coherence Tomography : Sistem pemindaian laser yang menggunakan tomografi koherensi optik (OCT) untuk mendapatkan gambar penampang. Sistem ini biasanya terdiri dari unit terkomputerisasi yang mencakup sumber cahaya, fotodetektor, dan layar video. OCT dapat menembus jaringan dan menampilkan data (misalnya, dinding pembuluh darah) sekitar dua atau tiga mm (0,08 hingga 0,12 inci), dan memberikan resolusi aksial dan lateral dalam orde mikrometer; Lot 4: Invasive Hemodynamic Monitor : adalah Sistem pemantauan fisiologis dirancang untuk penilaian berkelanjutan sistem kardiovaskular (KV) dan respons KV terhadap kebutuhan oksigen jaringan (yaitu, perfusi) menggunakan sensor minimal invasif yang bersumber dari jalur arteri. Sistem ini biasanya mencakup instrumen dan sensor untuk memperoleh data parameter dan monitor untuk menampilkan data dan/atau bentuk gelombang yang dibutuhkan untuk penilaian.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2188021);
